<?php
require_once __DIR__.'/accounting_core.php';
function install_accounting_schema(mysqli $db): void {
    $ddl=[
      "CREATE TABLE IF NOT EXISTS schema_migrations(version VARCHAR(100) PRIMARY KEY,checksum CHAR(64) NOT NULL,applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS finance_role_permissions(role_name VARCHAR(50) NOT NULL,permission VARCHAR(30) NOT NULL,allowed TINYINT NOT NULL,PRIMARY KEY(role_name,permission)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS accounts(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,account_group TINYINT NOT NULL,normal_balance ENUM('debit','credit') NOT NULL,parent_id INT UNSIGNED NULL,is_detail TINYINT NOT NULL DEFAULT 1,is_active TINYINT NOT NULL DEFAULT 1,report_class VARCHAR(40) NOT NULL,FOREIGN KEY(parent_id) REFERENCES accounts(id),CHECK(account_group BETWEEN 1 AND 5)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS cash_bank_accounts(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,account_id INT UNSIGNED NOT NULL UNIQUE,bank_name VARCHAR(100) NULL,account_number VARCHAR(100) NULL,is_active TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(account_id) REFERENCES accounts(id)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS accounting_periods(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,month CHAR(7) NOT NULL UNIQUE,status ENUM('open','closed') NOT NULL DEFAULT 'open',closed_by INT UNSIGNED NULL,closed_at DATETIME NULL) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS journal_entries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(40) NULL UNIQUE,entry_date DATE NOT NULL,period_id INT UNSIGNED NOT NULL,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,event VARCHAR(40) NOT NULL,description TEXT NOT NULL,status ENUM('draft','posted') NOT NULL DEFAULT 'draft',created_by INT UNSIGNED NOT NULL,posted_at DATETIME NULL,reversal_of BIGINT UNSIGNED NULL UNIQUE,UNIQUE KEY uq_journal_source(source_type,source_id,event),FOREIGN KEY(period_id) REFERENCES accounting_periods(id),FOREIGN KEY(reversal_of) REFERENCES journal_entries(id),INDEX(entry_date,status)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS journal_lines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,journal_entry_id BIGINT UNSIGNED NOT NULL,account_id INT UNSIGNED NOT NULL,debit DECIMAL(15,2) NOT NULL DEFAULT 0,credit DECIMAL(15,2) NOT NULL DEFAULT 0,department_id INT UNSIGNED NULL,batch VARCHAR(100) NULL,student_id INT NULL,vendor_id INT UNSIGNED NULL,party_name VARCHAR(255) NULL,document_type VARCHAR(40) NULL,document_id VARCHAR(100) NULL,cash_flow_class ENUM('operating','investing','financing','transfer','noncash') NOT NULL DEFAULT 'noncash',FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id),FOREIGN KEY(account_id) REFERENCES accounts(id),CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)),INDEX(account_id,journal_entry_id),INDEX(document_type,document_id)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS accounting_audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_type VARCHAR(40) NOT NULL,entity_id VARCHAR(100) NOT NULL,action VARCHAR(40) NOT NULL,actor_id INT UNSIGNED NOT NULL,actor_name VARCHAR(255) NOT NULL,details_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(entity_type,entity_id,id)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS accounting_idempotency(request_key VARCHAR(100) PRIMARY KEY,actor_id INT UNSIGNED NOT NULL,operation VARCHAR(50) NOT NULL,payload_hash CHAR(64) NOT NULL,result_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS vendors(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,is_active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS vendor_bills(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(50) NOT NULL UNIQUE,vendor_id INT UNSIGNED NOT NULL,bill_date DATE NOT NULL,due_date DATE NOT NULL,amount DECIMAL(15,2) NOT NULL,account_id INT UNSIGNED NOT NULL,liability_account_id INT UNSIGNED NOT NULL,status ENUM('draft','approved','cancelled') NOT NULL DEFAULT 'draft',created_by INT UNSIGNED NOT NULL,FOREIGN KEY(vendor_id) REFERENCES vendors(id),FOREIGN KEY(account_id) REFERENCES accounts(id),FOREIGN KEY(liability_account_id) REFERENCES accounts(id)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS accounting_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(40) NULL UNIQUE,request_key VARCHAR(100) NOT NULL UNIQUE,transaction_date DATE NOT NULL,type ENUM('income','expense','transfer') NOT NULL,classification VARCHAR(50) NOT NULL,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,source_number VARCHAR(100) NOT NULL,category VARCHAR(100) NOT NULL,description TEXT NOT NULL,amount DECIMAL(15,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'IDR',cash_account_id INT UNSIGNED NOT NULL,destination_cash_account_id INT UNSIGNED NULL,counter_account_id INT UNSIGNED NOT NULL,department_id INT UNSIGNED NULL,batch VARCHAR(100) NULL,student_id INT NULL,vendor_id INT UNSIGNED NULL,party_name VARCHAR(255) NOT NULL,payment_method VARCHAR(50) NOT NULL,reference VARCHAR(180) NOT NULL,approval_status ENUM('draft','submitted','approved','rejected','cancelled') NOT NULL DEFAULT 'draft',payment_status ENUM('unpaid','paid','verified','reversed') NOT NULL DEFAULT 'unpaid',journal_status ENUM('unposted','posted','reversed') NOT NULL DEFAULT 'unposted',created_by INT UNSIGNED NOT NULL,created_by_name VARCHAR(255) NOT NULL,approved_by INT UNSIGNED NULL,approved_by_name VARCHAR(255) NULL,approved_at DATETIME NULL,approval_note TEXT NULL,paid_at DATETIME NULL,verified_by INT UNSIGNED NULL,verified_at DATETIME NULL,journal_entry_id BIGINT UNSIGNED NULL UNIQUE,attachment_key CHAR(32) NULL,attachment_name VARCHAR(255) NULL,attachment_link VARCHAR(2048) NULL,legacy_finance_id INT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cash_account_id) REFERENCES cash_bank_accounts(id),FOREIGN KEY(destination_cash_account_id) REFERENCES cash_bank_accounts(id),FOREIGN KEY(counter_account_id) REFERENCES accounts(id),FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id),FOREIGN KEY(vendor_id) REFERENCES vendors(id),INDEX(transaction_date,source_type),INDEX(source_type,source_id),INDEX(approval_status,payment_status,journal_status)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS budget_commitments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,budget_item_id INT UNSIGNED NOT NULL,amount DECIMAL(15,2) NOT NULL,status ENUM('open','consumed','cancelled') NOT NULL DEFAULT 'open',created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(budget_item_id) REFERENCES budget_request_items(id)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS budget_realizations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_key VARCHAR(100) NOT NULL UNIQUE,budget_request_id INT UNSIGNED NOT NULL,budget_item_id INT UNSIGNED NOT NULL,amount DECIMAL(15,2) NOT NULL,classification ENUM('expense','asset','prepayment','vendor_bill') NOT NULL,vendor_id INT UNSIGNED NULL,vendor_bill_id INT UNSIGNED NULL,commitment_id BIGINT UNSIGNED NULL UNIQUE,transaction_id BIGINT UNSIGNED NULL UNIQUE,journal_entry_id BIGINT UNSIGNED NULL UNIQUE,status ENUM('recorded','cancelled') NOT NULL DEFAULT 'recorded',created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(budget_request_id) REFERENCES budget_requests(id),FOREIGN KEY(budget_item_id) REFERENCES budget_request_items(id),FOREIGN KEY(vendor_id) REFERENCES vendors(id),FOREIGN KEY(vendor_bill_id) REFERENCES vendor_bills(id),FOREIGN KEY(commitment_id) REFERENCES budget_commitments(id),FOREIGN KEY(transaction_id) REFERENCES accounting_transactions(id),FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id),INDEX(budget_item_id,status)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS accounting_source_documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,number VARCHAR(100) NOT NULL,document_date DATE NOT NULL,due_date DATE NULL,amount DECIMAL(15,2) NOT NULL,control_account_id INT UNSIGNED NOT NULL,recognition_account_id INT UNSIGNED NOT NULL,journal_entry_id BIGINT UNSIGNED NOT NULL UNIQUE,UNIQUE(source_type,source_id),FOREIGN KEY(control_account_id) REFERENCES accounts(id),FOREIGN KEY(recognition_account_id) REFERENCES accounts(id),FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id)) ENGINE=InnoDB",
      "CREATE TABLE IF NOT EXISTS payment_allocations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT UNSIGNED NOT NULL UNIQUE,source_document_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(15,2) NOT NULL,is_reversed TINYINT NOT NULL DEFAULT 0,FOREIGN KEY(transaction_id) REFERENCES accounting_transactions(id),FOREIGN KEY(source_document_id) REFERENCES accounting_source_documents(id)) ENGINE=InnoDB"
    ];
    foreach ($ddl as $sql) $db->query($sql);
    foreach (['department_id'=>'INT UNSIGNED NULL','approved_amount'=>'DECIMAL(15,2) NULL'] as $name=>$type) {
        if (!ac_one($db,'SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?',['budget_requests',$name])) $db->query("ALTER TABLE budget_requests ADD COLUMN $name $type");
    }
    if (!ac_one($db,'SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?',['budget_request_items','approved_amount'])) $db->query('ALTER TABLE budget_request_items ADD COLUMN approved_amount DECIMAL(15,2) NULL');
    // Expand enum additively; no old rows are reclassified or posted.
    $column=ac_one($db,"SHOW COLUMNS FROM budget_requests LIKE 'status'");
    if (!str_contains($column['Type'],'under_review')) $db->query("ALTER TABLE budget_requests MODIFY status ENUM('draft','submitted','under_review','approved','rejected','cancelled','partially_realized','fully_realized','closed') NOT NULL DEFAULT 'draft'");
    foreach (['read','prepare','approve','post','configure'] as $permission) foreach (['finance','admin','super_admin','director','direktur'] as $role) {
        $allowed=in_array($role,['finance'],true)?in_array($permission,['read','prepare','post'],true):($permission==='read'||$permission==='approve'||($permission==='configure'&&in_array($role,['admin','super_admin'],true)));
        ac_query($db,'INSERT IGNORE INTO finance_role_permissions(role_name,permission,allowed) VALUES(?,?,?)',[$role,$permission,(int)$allowed]);
    }
    // Template accounts are configurable master data, never fake transaction/KPI data.
    $template=[['1100','Kas / Bank',1,'debit','cash'],['1200','Piutang Usaha',1,'debit','receivable'],['1300','Persediaan',1,'debit','inventory'],['1400','Aset Tetap',1,'debit','fixed_asset'],['1500','Uang Muka',1,'debit','prepayment'],['2100','Utang Usaha',2,'credit','payable'],['2200','Utang Gaji',2,'credit','payroll_payable'],['2300','Utang Pinjaman',2,'credit','loan'],['2400','Pendapatan Diterima di Muka',2,'credit','deferred_revenue'],['2500','Utang Reimbursement',2,'credit','reimbursement_payable'],['2600','Utang Pajak / Potongan',2,'credit','tax_payable'],['3100','Modal Disetor',3,'credit','capital'],['3200','Laba Ditahan',3,'credit','retained_earnings'],['4100','Pendapatan Pelatihan',4,'credit','revenue'],['4200','Pendapatan Lain',4,'credit','other_income'],['5100','Biaya Layanan',5,'debit','cost_of_services'],['5200','Beban Operasional',5,'debit','operating_expense'],['5300','Beban Gaji',5,'debit','operating_expense'],['5400','Beban Bunga',5,'debit','other_expense'],['5500','Beban Pajak Penghasilan',5,'debit','income_tax']];
    foreach($template as $row) ac_query($db,'INSERT IGNORE INTO accounts(code,name,account_group,normal_balance,report_class) VALUES(?,?,?,?,?)',$row);
    // Posted journals and their lines are immutable even through direct SQL.
    $guards=[
      'ac_journal_update'=>"BEFORE UPDATE ON journal_entries FOR EACH ROW BEGIN IF OLD.status='posted' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted journal is immutable'; END IF; END",
      'ac_journal_delete'=>"BEFORE DELETE ON journal_entries FOR EACH ROW BEGIN IF OLD.status='posted' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted journal cannot be deleted'; END IF; END",
      'ac_line_insert'=>"BEFORE INSERT ON journal_lines FOR EACH ROW BEGIN IF (SELECT status FROM journal_entries WHERE id=NEW.journal_entry_id)='posted' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted lines are immutable'; END IF; END",
      'ac_line_update'=>"BEFORE UPDATE ON journal_lines FOR EACH ROW BEGIN IF (SELECT status FROM journal_entries WHERE id=OLD.journal_entry_id)='posted' OR (SELECT status FROM journal_entries WHERE id=NEW.journal_entry_id)='posted' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted lines are immutable'; END IF; END",
      'ac_line_delete'=>"BEFORE DELETE ON journal_lines FOR EACH ROW BEGIN IF (SELECT status FROM journal_entries WHERE id=OLD.journal_entry_id)='posted' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted lines are immutable'; END IF; END",
      'ac_journal_balance'=>"BEFORE UPDATE ON journal_entries FOR EACH ROW BEGIN IF NEW.status='posted' AND ((SELECT COUNT(*) FROM journal_lines WHERE journal_entry_id=NEW.id)<2 OR (SELECT COALESCE(SUM(debit-credit),1) FROM journal_lines WHERE journal_entry_id=NEW.id)<>0 OR (SELECT status FROM accounting_periods WHERE id=NEW.period_id)<>'open') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Journal unbalanced or period closed'; END IF; END"
    ];
    $guards['ac_journal_insert']='BEFORE INSERT ON journal_entries FOR EACH ROW BEGIN IF NEW.status<>\'draft\' THEN SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT=\'Journal must start as draft\'; END IF; END';
    $guards['ac_audit_update']='BEFORE UPDATE ON accounting_audit_logs FOR EACH ROW SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT=\'Audit logs are immutable\'';
    $guards['ac_audit_delete']='BEFORE DELETE ON accounting_audit_logs FOR EACH ROW SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT=\'Audit logs are immutable\'';
    foreach($guards as $name=>$definition) if(!ac_one($db,'SELECT TRIGGER_NAME FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME=?',[$name])) $db->query("CREATE TRIGGER $name $definition");
    ac_query($db,'INSERT IGNORE INTO schema_migrations(version,checksum) VALUES(?,?)',['finance_traceability_v1',hash_file('sha256',__FILE__)]);
}
